    match state.revoke_grant(req.user_id, &req.client_id).await {
        true => (StatusCode::OK, Json(serde_json::json!({"revoked": true}))).into_response(),
        false => (
            StatusCode::NOT_FOUND,
            Json(serde_json::json!({"error": "no_active_grant"})),
        )
            .into_response(),
    }
}

