/// Phase 3: key rotation — token signed with new key validates after one refresh.
#[tokio::test]
async fn phase3_key_rotation_one_refresh_on_unknown_kid() {
    // Two keys: old and new.
    let (_old_key, old_jwk) = generate_rsa_key("old-key");
    let (new_key, new_jwk) = generate_rsa_key("new-key");

    let mock_issuer = "https://auth.example.com".to_string();
    let mock = wiremock::MockServer::start().await;
    let jwks_uri = format!("{}/jwks", mock.uri());

    // Discovery metadata.
    wiremock::Mock::given(wiremock::matchers::method("GET"))
        .and(wiremock::matchers::path("/.well-known/oauth-authorization-server"))
        .respond_with(
            wiremock::ResponseTemplate::new(200)
                .insert_header("content-type", "application/json")
                .set_body_string(serde_json::json!({
                    "issuer": mock_issuer,
                    "jwks_uri": jwks_uri,
                })
                .to_string()),
        )
        .mount(&mock)
        .await;

    // First JWKS response: only the old key (simulates pre-rotation state).
    // Second JWKS response (after refresh): both keys (rotation overlap).
    wiremock::Mock::given(wiremock::matchers::method("GET"))
        .and(wiremock::matchers::path("/jwks"))
        .respond_with(
            wiremock::ResponseTemplate::new(200)
                .insert_header("content-type", "application/json")
                .set_body_string(serde_json::json!({ "keys": [old_jwk] }).to_string()),
        )
        .expect(1)
        .mount(&mock)
        .await;

    wiremock::Mock::given(wiremock::matchers::method("GET"))
        .and(wiremock::matchers::path("/jwks"))
        .respond_with(
            wiremock::ResponseTemplate::new(200)
                .insert_header("content-type", "application/json")
                .set_body_string(serde_json::json!({ "keys": [old_jwk.clone(), new_jwk] }).to_string()),
        )
        .expect(1..)
        .mount(&mock)
        .await;

    // Token signed with the new key.
    let now = std::time::SystemTime::now()
        .duration_since(std::time::UNIX_EPOCH)
        .unwrap()
        .as_secs() as i64;
    let claims = serde_json::json!({
        "iss": mock_issuer,
        "sub": "42",
        "aud": TEST_RESOURCE,
        "exp": now + 300,
        "iat": now,
        "jti": "t6",
        "client_id": "client-abc",
        "scope": "commoncal.calendar.metadata.read",
    });
    let token = sign_jwt(&new_key, "new-key", &claims);

    let validator = TokenValidator::new();
    let result = validator.validate(&token, &mock_issuer, TEST_RESOURCE).await;
    assert!(
        result.is_ok(),
        "token signed with new key should validate after one refresh, got: {:?}",
        result
    );
}

