                .set_body_string(serde_json::json!({
                    "issuer": mock_issuer,
                    "jwks_uri": jwks_uri,
                })
                .to_string()),
        )
        .mount(&mock)
        .await;

    // First JWKS response: only the old key (simulates pre-rotation state).
    wiremock::Mock::given(wiremock::matchers::method("GET"))
        .and(wiremock::matchers::path("/jwks"))
        .respond_with(
            wiremock::ResponseTemplate::new(200)
                .insert_header("content-type", "application/json")
                .set_body_string(serde_json::json!({ "keys": [old_jwk] }).to_string()),
        )
        .expect(1)
        .mount(&mock)
        .await;

    // Second JWKS response (after refresh): both keys (rotation overlap).
    wiremock::Mock::given(wiremock::matchers::method("GET"))
        .and(wiremock::matchers::path("/jwks"))
        .respond_with(
            wiremock::ResponseTemplate::new(200)
                .insert_header("content-type", "application/json")
                .set_body_string(serde_json::json!({ "keys": [old_jwk.clone(), new_jwk] }).to_string()),
        )
        .expect(1..)
        .mount(&mock)
        .await;

    // Token signed with the new key.
    let now = std::time::SystemTime::now()
        .duration_since(std::time::UNIX_EPOCH)
        .unwrap()
        .as_secs() as i64;
    let claims = serde_json::json!({
        "iss": mock_issuer,
